from scipy.optimize import differential_evolution
# blue inside groups, arbitrary red cross
for k in [3,4,5,6]:
 for alpha in [.17,.2,.21,.3]:
  ij=[(i,j) for i in range(k) for j in range(i+1,k)]
  def fun(z,ret=False):
   w=z[:k]; w=w/w.sum(); P=np.zeros((k,k))
   for v,(i,j) in zip(z[k:],ij):P[i,j]=P[j,i]=v
   A=(P*w)@P; Q=1-P; B=(Q*w)@Q
   a=max(A[i,j] for i,j in ij);b=B.max()
   return (min(alpha/a,1/b),w,P) if ret else max(a/alpha,b)
  res=differential_evolution(fun,[(.01,1)]*k+[(.001,.999)]*len(ij),popsize=12,maxiter=1800,tol=1e-8)
  print(k,alpha,fun(res.x,True)[0],flush=True)
