{"content":"import numpy as np
from scipy.optimize import differential_evolution
for k in [2,3,4]:
 for nr in range(1,k+1):
  for alpha in [.17,.2,.21,.3,.5]:
   ij=[(i,j) for i in range(k) for j in range(i+1,k)]
   diag=[1]*nr+[0]*(k-nr)
   def fun(z,ret=False):
    w=z[:k]; w=w/w.sum(); P=np.diag(diag).astype(float)
    for v,(i,j) in zip(z[k:],ij):P[i,j]=P[j,i]=v
    A=(P*w)@P; Q=1-P; B=(Q*w)@Q
    a=max([A[i,j] for i,j in ij]+[A[i,i] for i in range(nr)])
    b=max([B[i,j] for i,j in ij]+[B[i,i] for i in range(nr,k)]+[0])
    return (min(alpha/a,1/b),w,P) if ret else max(a/alpha,b)
   res=differential_evolution(fun,[(.00001,1)]*k+[(.00001,.99999)]*len(ij),popsize=10,maxiter=600,tol=1e-7)
   v=fun(res.x,True)[0]
   print(k,nr,alpha,round(v,6),flush=True)
