    b=max([B[i,j] for i,j in ij+nij]+[B[i,i] for i in range(k) if i!=red])
    return (min(alpha/a,1/b),w,P) if ret else max(a/alpha,b)
   res=differential_evolution(fun,[(.00001,1)]*k+[(.00001,.99999)]*len(ij),popsize=5,maxiter=200,tol=1e-5)
   v=fun(res.x,True)[0]
   if v>best[0]+1e-4:
    best=(v,(nx.to_graph6_bytes(G).strip(),red)); print(alpha,best,flush=True)
